"use strict";
(()=>{
const D=window.researchData,R=D.report,S=R.selected,H=R.parameters.hold_market_sessions||20,$=s=>document.querySelector(s);
const pct=(x,d=2)=>x===null?'—':`${x>0?'+':''}${(x*100).toFixed(d)}%`,win=x=>(x*100).toFixed(2)+'%',num=x=>Number(x).toLocaleString('zh-CN'),day=x=>String(x).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3'),cl=x=>x>0?'gain':x<0?'loss':'neutral';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#research-stats').innerHTML=[['组合年化',pct(S.cagr),'累计净收益 '+pct(S.total)],['最大回撤',pct(S.max_drawdown),'每日收盘权益计算'],['成交胜率',win(S.trade_stats.win),S.fills+' 笔成交 · '+S.active_entry_dates+' 个买入日'],['盈亏比',S.trade_stats.payoff.toFixed(2),'平均盈利 / 平均亏损绝对值']].map(([a,b,c])=>`<article><div><h2>${a}</h2><strong>${b}</strong><p>${c}</p></div></article>`).join('');
$('#annual').innerHTML=S.annual.map((v,i)=>{const t=S.annual_trade_stats[i];return `<tr><td>${2022+i}${i===4?'（截至快照）':''}</td><td class="${cl(v)}">${pct(v)}</td><td class="loss">${pct(S.annual_drawdown[i])}</td><td>${t.n}</td><td>${win(t.win)}</td><td>${(t.payoff==null?'—':t.payoff.toFixed(2))}</td><td class="${cl(t.mean)}">${pct(t.mean)}</td></tr>`}).join('');
$('#equity-foot').innerHTML=`<span>期末资产 <b>${num(Math.round((1+S.total)*1000000))} 元</b></span><span>平均仓位 <b>${win(S.average_exposure)}</b></span><span>订单 ${S.reservations} 笔 · 成交 ${S.fills} 笔</span><span>计划持有 ${H} 个交易日，含买入日</span>`;
const labels={volume:'阳/阴日均量门槛',window:'量能观察日数',pit:'最低跌幅',age:'距最低点交易日',rise:'信号前距最低价涨幅',move:'信号涨幅上限',market:'市场当日涨幅下限',slots:'最大持仓数',cost:'往返总成本',rank:'同日排序',discount:'次日挂单折价',hold:'持有交易日'};
const vals={code:'股票代码',random:'固定随机顺序',low_liquidity:'成交额由低到高'};
if(R.sensitivity.length)$('#sensitivity').innerHTML=R.sensitivity.map(v=>`<tr><td>${labels[v.change]} ${vals[v.value]||(v.change==='volume'?v.value.toFixed(2)+'倍':['age','slots','hold','window'].includes(v.change)?v.value:win(v.value))}</td><td>${pct(v.cagr)}</td><td>${pct(v.max_drawdown)}</td><td>${pct(v.annual[4])}</td></tr>`).join('');
$('#holds').innerHTML=R.horizons.map(h=>`<tr><td>${h.hold} 日</td><td>${h.trade_stats.n}</td><td>${win(h.trade_stats.win)}</td><td>${h.trade_stats.payoff.toFixed(2)}</td><td>${pct(h.trade_stats.mean)}</td><td>${pct(h.cagr)}</td><td>${pct(h.max_drawdown)}</td></tr>`).join('');
$('#rolling').innerHTML=R.chronological.map(x=>`<tr><td>${x.year}</td><td>${pct(x.actual_return)}</td><td>${pct(x.drawdown)}</td><td>${x.trades}</td></tr>`).join('');
function chart(){const canvas=$('#equity-chart'),w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const a=D.equity,lo=.9,hi=Math.max(...a.map(x=>x[1]))*1.04,left=50,right=w-16,top=16,bottom=h-30,x=i=>left+i/(a.length-1)*(right-left),y=v=>top+(hi-v)/(hi-lo)*(bottom-top);c.font='11px system-ui';for(let v=1;v<=hi;v+=.5){c.strokeStyle='#e8e8f2';c.beginPath();c.moveTo(left,y(v));c.lineTo(right,y(v));c.stroke();c.fillStyle='#7c839b';c.fillText(v.toFixed(1),9,y(v)+4)}c.beginPath();a.forEach((v,i)=>i?c.lineTo(x(i),y(v[1])):c.moveTo(x(i),y(v[1])));c.strokeStyle='#6655c9';c.lineWidth=2;c.stroke();c.lineTo(right,bottom);c.lineTo(left,bottom);c.closePath();c.fillStyle='#6655c90c';c.fill();let year=0;a.forEach((v,i)=>{let yy=Math.floor(v[0]/10000);if(yy!==year){year=yy;c.fillStyle='#737c93';c.fillText(yy,x(i),h-7)}})}new ResizeObserver(chart).observe($('#equity-chart'));
let page=0,visible=[],cleanup=null,opener=null;const size=15;
function filter(){const scope=$('#trade-scope').value,year=$('#trade-year').value,q=$('#trade-search').value.trim().toLowerCase(),sort=$('#trade-sort').value;visible=D.rows.filter(x=>(scope==='all'?x.independent:x.executed)&&(year==='all'||String(x.signal_date).startsWith(year))&&(!q||(x.name+x.code).toLowerCase().includes(q)));visible.sort((a,b)=>sort==='netasc'?a.net-b.net:sort==='netdesc'?b.net-a.net:b.signal_date-a.signal_date||a.code.localeCompare(b.code));page=0;table()}
function table(){const slice=visible.slice(page*size,(page+1)*size);$('#trade-rows').innerHTML=slice.length?slice.map(x=>`<tr><td><button class="research-stock" data-event="${x.event_id}"><strong>${esc(x.name)}</strong><small>${esc(x.code)}</small></button></td><td>${day(x.signal_date)}</td><td>${day(x.entry_date)}</td><td>${x.buy_price.toFixed(2)}</td><td>${day(x.exit_date)}</td><td class="${cl(x.net)}">${pct(x.net)}</td><td>${x.executed?'组合成交':'独立信号样本'}</td></tr>`).join(''):'<tr><td colspan="7">没有符合条件的信号</td></tr>';$('#trade-count').textContent=`共 ${num(visible.length)} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(visible.length/size))} 页`;$('#prev-page').disabled=page===0;$('#next-page').disabled=(page+1)*size>=visible.length}
for(const id of ['trade-scope','trade-year','trade-sort'])$('#'+id).addEventListener('change',filter);$('#trade-search').addEventListener('input',filter);$('#prev-page').addEventListener('click',()=>{page--;table()});$('#next-page').addEventListener('click',()=>{page++;table()});
const dialog=$('#research-detail');$('#trade-rows').addEventListener('click',ev=>{const button=ev.target.closest('[data-event]');if(!button)return;opener=button;const row=D.rows.find(x=>x.event_id===Number(button.dataset.event));$('#detail-name').textContent=row.name;$('#detail-subtitle').textContent=row.code+' · 信号日 '+day(row.signal_date)+' · '+(row.executed?'组合成交':'独立信号样本');$('#detail-metrics').innerHTML=[['买入价',row.buy_price.toFixed(2)],[H+' 日净收益',pct(row.net)],['前期跌幅',win(row.drawdown)],['市场当日涨幅',pct(row.daily)]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('');$('#detail-rule').textContent=`放量倍数 ${row.volume5.toFixed(2)} × 前5日、${row.volume10.toFixed(2)} × 前10日。信号涨幅 ${pct(row.signal_return)}。市场近20日收益 ${pct(row.market20)}。买入 ${day(row.entry_date)}，卖出 ${day(row.exit_date)}。`;if(cleanup)cleanup();const root=dialog.querySelector('.candle-panel');root.querySelector('canvas').hidden=false;root.querySelector('select').value='60';root.querySelector('select').disabled=true;root.querySelector('.candle-info').textContent='正在加载行情…';dialog.showModal();cleanup=window.mountSignalCandles(root,row,null)});$('#close-detail').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(cleanup)cleanup();cleanup=null;opener?.focus()});dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)dialog.close()}});filter();
})();

(()=>{const D=window.researchData,R=D.report,$=s=>document.querySelector(s),p=x=>(x*100).toFixed(2)+'%';
const names={none:'不加条件','bullavg40_ge1.0':'40日阳/阴均量≥1','bullavg60_ge1.2':'60日阳/阴均量≥1.2','bullavg120_ge1.0':'120日阳/阴均量≥1',down_volume_dry:'阴量缩至此前80%以下',divergence:'严格MACD底背离',near_divergence:'近似双底的MACD背离',macd_hist_turn:'MACD柱连续回升',weekly_momentum:'已完成周线动能改善',monthly_momentum:'已完成月线动能改善',monthly_hist_up:'已完成月线MACD柱上升',volume_weekly:'40日阳量优势＋周线改善',long250_none:'250日背景，不加量能周线','long250_bullavg40_ge1.0':'250日背景＋阳量优势',long250_weekly_momentum:'250日背景＋周线改善',long250_volume_weekly:'250日背景＋阳量优势＋周线改善'};
$('#comparisons').innerHTML=R.comparisons.map((x,i)=>'<tr><td><a href="'+['research.html','multiframe.html','macd.html'][i]+'">'+x.label+'</a></td><td>'+p(x.cagr)+'</td><td>'+p(x.max_drawdown)+'</td><td>'+p(x.trade_stats.win)+'</td><td>'+x.trade_stats.payoff.toFixed(2)+'</td><td>'+x.fills+'</td></tr>').join('');
$('#ablations').innerHTML=R.ablations.map(x=>'<tr><td>'+names[x.condition]+'</td><td>'+p(x.cagr)+'</td><td>'+p(x.max_drawdown)+'</td><td>'+x.fills+'</td></tr>').join('');
const rankNames={liquidity:'成交额',volume:'阳阴量比',macd:'MACD',volume_macd:'阳阴量比＋MACD'};
$('#ranking-comparison').innerHTML=R.ranking_comparison.map(x=>'<tr><td>'+x.hold+'日</td><td>'+rankNames[x.rank]+'</td><td>'+p(x.cagr)+'</td><td>'+p(x.max_drawdown)+'</td><td>'+p(x.trade_stats.win)+'</td><td>'+x.trade_stats.payoff.toFixed(2)+'</td><td>'+x.fills+'</td></tr>').join('');
if(!R.horizons.length)$('#holds').innerHTML='<tr><td colspan="7"><a href="multiframe.html#evidence">查看20日平衡版的四种持有期对照</a></td></tr>';
$('#trade-rows').addEventListener('click',ev=>{const b=ev.target.closest('[data-event]');if(!b)return;const x=D.rows.find(x=>x.event_id===Number(b.dataset.event));$('#detail-rule').textContent+=' 近40日阳/阴日均量比 '+x.vol_mean_40.toFixed(2)+'，阳量占比 '+p(x.vol_share_40)+'。已完成周截止 '+x.w_bar_date+'，周动能改善 '+(x.w_mom_improving?'是':'否')+'。日MACD底背离候选 '+(x.near_divergence?'是':'否')+'。';});
})();
